class Solution {
public:
    bool checkPerfectNumber(int num) {
        if (num <= 1) return false;
        int total = 1;
        for (int d = 2; d * d <= num; d++) {
            if (num % d == 0) {
                total += d;
                if (d * d < num) total += num / d;
            }
        }
        return total == num;
    }
};

class Solution {
    public boolean checkPerfectNumber(int num) {
        if (num <= 1) return false;
        int total = 1;
        for (int d = 2; d * d <= num; d++) {
            if (num % d == 0) {
                total += d;
                if (d * d < num) total += num / d;
