var checkPerfectNumber = function(num) {
    if (num <= 1) return false;
    let total = 1;
    for (let d = 2; d * d <= num; d++) {
        if (num % d === 0) {
            total += d;
            if (d * d < num) total += Math.floor(num / d);
        }
    }
    return total === num;
};
